#!/usr/bin/env bash
# Quality Run — the single deterministic gate shared by the agent and by Git (pre-push).
# Check-only: never formats, fixes or installs. Generated by the quality-gate-lefthook skill.
#
# usage: scripts/quality/run.sh [--stage STAGE]... [--path PATH]...
#   STAGE: format | static | security | deadcode | complexity | duplication | tests | all (default)
#   PATH:  scan only these files/dirs (format, static, security, complexity) and keep only their
#          failures in the report. deadcode, duplication and tests always scan the whole project.
set -uo pipefail

ROOT="${CLAUDE_PROJECT_DIR:-$(pwd)}"
cd "$ROOT"

OUT="${QUALITY_OUT:-.quality}"
export QUALITY_OUT="${OUT}"
BASELINE="quality-baseline.json"
ALL_STAGES=(format static security deadcode complexity duplication tests)
STAGES=()
SCOPE=()

usage() {
  echo "usage: scripts/quality/run.sh [--stage ${ALL_STAGES[*]// /|}|all]... [--path PATH]..." >&2
}

while [[ $# -gt 0 ]]; do
  case "$1" in
    --stage)
      IFS=',' read -r -a p_list <<< "${2:-}"
      STAGES+=("${p_list[@]}")
      shift 2
      ;;
    --path) SCOPE+=("${2:-}"); shift 2 ;;
    -h|--help) usage; exit 0 ;;
    *) usage; exit 2 ;;
  esac
done

if [[ ${#STAGES[@]} -eq 0 ]] || [[ " ${STAGES[*]} " == *" all "* ]]; then
  STAGES=("${ALL_STAGES[@]}")
fi
for p_stage in "${STAGES[@]}"; do
  if [[ " ${ALL_STAGES[*]} " != *" ${p_stage} "* ]]; then
    echo "unknown stage: ${p_stage}" >&2
    usage
    exit 2
  fi
done

# Scan roots: the --path entries that exist, or the whole project.
FIND_ROOTS=(.)
if [[ ${#SCOPE[@]} -gt 0 ]]; then
  FIND_ROOTS=()
  for p_scope in "${SCOPE[@]}"; do
    p_scope="${p_scope%/}"
    [[ -n "$p_scope" && -e "$p_scope" ]] && FIND_ROOTS+=("$p_scope")
  done
fi
scoped() { [[ ${#SCOPE[@]} -gt 0 ]]; }

if ! command -v jq >/dev/null 2>&1; then
  echo "jq not found. Run quality-gate-lefthook SETUP." >&2
  exit 2
fi

baseline() {
  local p_key="$1" p_default="$2"
  if [[ -f "$BASELINE" ]]; then
    jq -r --arg d "$p_default" ".${p_key} // \$d" "$BASELINE"
  else
    echo "$p_default"
  fi
}

CYCLOMATIC_MAX="$(baseline cyclomatic_max 10)"
COGNITIVE_MAX="$(baseline cognitive_max 15)"
DUPLICATION_MAX="$(baseline duplication_max_percent 3)"

rm -rf "$OUT"
mkdir -p "$OUT"

join_by() {
  local p_sep="$1"
  shift
  local p_out="${1:-}"
  shift || true
  local p_item
  for p_item in "$@"; do p_out="${p_out}${p_sep}${p_item}"; done
  echo "$p_out"
}

EXCLUDE_DIRS=(.git .quality node_modules vendor .venv venv dist build coverage graphify-out)

# Files matching the given extensions under the given roots, skipping EXCLUDE_DIRS. No git.
find_files() {
  local p_roots=() p_names=() p_prune=() p_ext p_dir
  while [[ $# -gt 0 && "$1" != "--" ]]; do p_roots+=("$1"); shift; done
  shift
  [[ ${#p_roots[@]} -gt 0 ]] || return 0
  for p_ext in "$@"; do p_names+=(-o -name "*.${p_ext}"); done
  for p_dir in "${EXCLUDE_DIRS[@]}"; do p_prune+=(-o -name "${p_dir}"); done
  find "${p_roots[@]}" \( "${p_prune[@]:1}" \) -prune -o -type f \( "${p_names[@]:1}" \) -print 2>/dev/null \
    | sed 's|^\./||' | sort -u
}
list_files()     { find_files "${FIND_ROOTS[@]+"${FIND_ROOTS[@]}"}" -- "$@"; }  # scan scope
list_all_files() { find_files . -- "$@"; }                                       # whole project

# Tool targets: the scoped files, or "." for the whole project.
targets() {
  if scoped; then list_files "$@"; else echo .; fi
}

has_python() { [[ -f pyproject.toml || -f uv.lock ]] || [[ -n "$(list_all_files py | head -1)" ]]; }
has_go()     { [[ -f go.mod ]] || [[ -n "$(list_all_files go | head -1)" ]]; }
has_js()     { [[ -f package.json ]] || [[ -n "$(list_all_files ts tsx js jsx mjs cjs | head -1)" ]]; }

wants() { [[ " ${STAGES[*]} " == *" $1 "* ]]; }

# Normalized failure line (JSON Lines) for tools without JSON/SARIF output.
emit() {
  local p_tool="$1" p_stage="$2" p_rule="$3" p_file="$4" p_line="$5" p_msg="$6"
  jq -cn --arg tool "$p_tool" --arg stage "$p_stage" --arg rule "$p_rule" \
    --arg file "$p_file" --argjson line "${p_line:-0}" --arg message "$p_msg" \
    '{tool:$tool, stage:$stage, rule:$rule, severity:"error", file:$file, line:$line, message:$message}' \
    >> "${OUT}/${p_tool}.norm.jsonl"
}

# Records a missing tool as a failure so the gate stays red until SETUP runs.
need() {
  local p_bin="$1" p_tool="$2" p_stage="$3"
  if command -v "$p_bin" >/dev/null 2>&1; then
    return 0
  fi
  emit "$p_tool" "$p_stage" "tool-missing" "" 0 "${p_bin} not on PATH; run quality-gate-lefthook SETUP"
  return 1
}

# Runs a tool; stdout+stderr go to .quality/<tool>.log, exit code to .quality/<tool>.exit.
# aggregate.sh turns a missing/invalid report into a tool-error failure.
run() {
  local p_tool="$1"
  shift
  "$@" > "${OUT}/${p_tool}.log" 2>&1
  echo "$?" > "${OUT}/${p_tool}.exit"
}

# "file:line:..." text output -> normalized lines.
emit_text() {
  local p_tool="$1" p_stage="$2" p_rule="$3" p_src="$4"
  local p_file p_line p_msg
  [[ -f "$p_src" ]] || return 0
  while IFS= read -r p_row; do
    p_file="${p_row%%:*}"
    p_line="$(echo "$p_row" | cut -d: -f2)"
    [[ "$p_line" =~ ^[0-9]+$ ]] || continue
    p_msg="$(echo "$p_row" | cut -d: -f3- | sed 's/^[0-9]*: *//; s/^ *//')"
    emit "$p_tool" "$p_stage" "$p_rule" "$p_file" "$p_line" "$p_msg"
  done < "$p_src"
}

# Project stacks (deadcode, duplication, tests) and scan stacks (scoped stages).
GO_ALL=0; PY_ALL=0; JS_ALL=0
has_go && GO_ALL=1
has_python && PY_ALL=1
has_js && JS_ALL=1
GO=$GO_ALL; PY=$PY_ALL; JS=$JS_ALL
if scoped; then
  [[ -n "$(list_files go | head -1)" ]] || GO=0
  [[ -n "$(list_files py | head -1)" ]] || PY=0
  [[ -n "$(list_files ts tsx js jsx mjs cjs | head -1)" ]] || JS=0
fi
mapfile -t PY_T  < <(targets py)
mapfile -t JS_T  < <(targets ts tsx js jsx mjs cjs)
if scoped; then
  mapfile -t GO_PKGS < <(list_files go | xargs -r -n1 dirname | sort -u | sed 's|^|./|; s|^\./\./|./|')
else
  GO_PKGS=(./...)
fi

# Single-path tools: run once per scan root and merge the SARIF runs into <tool>.sarif.
# Args use {ROOT} and {SARIF} placeholders.
run_per_root() {
  local p_tool="$1"
  shift
  local p_i=0 p_rc=0 p_root p_part p_parts=()
  : > "${OUT}/${p_tool}.log"
  for p_root in "${FIND_ROOTS[@]}"; do
    p_i=$((p_i + 1))
    p_part="${OUT}/${p_tool}.part${p_i}.tmp"
    local p_cmd=("${@//\{ROOT\}/$p_root}")
    p_cmd=("${p_cmd[@]//\{SARIF\}/$p_part}")
    "${p_cmd[@]}" >> "${OUT}/${p_tool}.log" 2>&1 || p_rc=$?
    jq -e . "$p_part" >/dev/null 2>&1 && p_parts+=("$p_part")
  done
  if [[ ${#p_parts[@]} -gt 0 ]]; then
    jq -s '{version: (.[0].version // "2.1.0"), "$schema": .[0]["$schema"], runs: [.[].runs[]]}' \
      "${p_parts[@]}" > "${OUT}/${p_tool}.sarif"
  fi
  rm -f "${OUT}/${p_tool}".part*.tmp
  echo "$p_rc" > "${OUT}/${p_tool}.exit"
}

# ---------------------------------------------------------------- format
if wants format; then
  if [[ $GO -eq 1 ]] && need gofmt gofmt format; then
    mapfile -t p_go < <(list_files go)
    if [[ ${#p_go[@]} -gt 0 ]]; then
      gofmt -l "${p_go[@]}" 2>"${OUT}/gofmt.log" | while read -r p_f; do
        emit gofmt format gofmt "$p_f" 0 "file is not gofmt-formatted"
      done
    fi
  fi
  if [[ $PY -eq 1 ]] && need ruff ruff-format format; then
    ruff format --check "${PY_T[@]}" 2>&1 | sed -n 's/^Would reformat: //p' | while read -r p_f; do
      emit ruff-format format ruff-format "$p_f" 0 "file is not ruff-formatted"
    done
  fi
  if [[ $JS -eq 1 ]] && need biome biome-format format; then
    run biome-format biome format --no-errors-on-unmatched --reporter=sarif --reporter-file="${OUT}/biome-format.sarif" "${JS_T[@]}"
  fi
fi

# ---------------------------------------------------------------- static analysis
if wants static; then
  if [[ $GO -eq 1 ]] && need staticcheck staticcheck static; then
    staticcheck -f sarif -checks "inherit,-U1000" "${GO_PKGS[@]}" > "${OUT}/staticcheck.sarif" 2> "${OUT}/staticcheck.log"
    echo "$?" > "${OUT}/staticcheck.exit"
  fi
  if [[ $PY -eq 1 ]]; then
    if need ruff ruff-check static; then
      run ruff-check ruff check --output-format sarif --output-file "${OUT}/ruff-check.sarif" "${PY_T[@]}"
    fi
    if need mypy mypy static; then
      mypy --output json "${PY_T[@]}" > "${OUT}/mypy.jsonl" 2> "${OUT}/mypy.log"
      echo "$?" > "${OUT}/mypy.exit"
    fi
  fi
  if [[ $JS -eq 1 ]] && need biome biome-lint static; then
    run biome-lint biome lint --no-errors-on-unmatched \
      --skip=security --skip=complexity/noExcessiveCognitiveComplexity \
      --reporter=sarif --reporter-file="${OUT}/biome-lint.sarif" "${JS_T[@]}"
  fi
fi

# ---------------------------------------------------------------- security
# Nothing to scan (every --path missing) -> skip; never fall back to the whole project.
if wants security && [[ ${#FIND_ROOTS[@]} -gt 0 ]]; then
  if need gitleaks gitleaks security; then
    run_per_root gitleaks gitleaks dir "{ROOT}" --config .gitleaks.toml --redact --no-banner --exit-code 0 \
      --report-format sarif --report-path "{SARIF}"
  fi
  if need semgrep semgrep security; then
    mapfile -t p_configs < <(baseline 'semgrep_configs | join("\n")' "p/default")
    p_args=()
    for p_c in "${p_configs[@]}"; do p_args+=(--config "$p_c"); done
    run semgrep semgrep scan "${p_args[@]}" --metrics=off --quiet --severity WARNING --severity ERROR \
      --sarif --output "${OUT}/semgrep.sarif" "${FIND_ROOTS[@]}"
    # Decision #11 (specs/decisions.md): drop ONLY the listed rule ids (exact match) and ONLY in *_test.go.
    mapfile -t p_test_rules < <(baseline 'semgrep_test_exclude_rules // [] | join("\n")' "")
    if [[ -n "${p_test_rules[*]}" ]] && jq -e . "${OUT}/semgrep.sarif" >/dev/null 2>&1; then
      p_rules_json="$(printf '%s\n' "${p_test_rules[@]}" | jq -R . | jq -cs 'map(select(length > 0))')"
      jq --argjson rules "$p_rules_json" '
        .runs[]?.results |= ((. // []) | map(select(
          ((.ruleId // "") as $r | $rules | index($r)) != null
          and ((.locations[0].physicalLocation.artifactLocation.uri // "") | test("(^|/)[^/]*_test\\.go$"))
          | not)))' "${OUT}/semgrep.sarif" > "${OUT}/semgrep.sarif.tmp" \
        && mv "${OUT}/semgrep.sarif.tmp" "${OUT}/semgrep.sarif"
    fi
    # Decision #13: drop ONLY the listed container rule ids on ONLY the exact listed paths (relative to the project root).
    p_ct_rules="$(baseline 'semgrep_container_exclude.rules | tojson' "[]")"
    p_ct_paths="$(baseline 'semgrep_container_exclude.paths | tojson' "[]")"
    if [[ "$p_ct_rules" != "[]" && "$p_ct_paths" != "[]" ]] && jq -e . "${OUT}/semgrep.sarif" >/dev/null 2>&1; then
      jq --argjson rules "$p_ct_rules" --argjson paths "$p_ct_paths" --arg pwd "$PWD/" '
        .runs[]?.results |= ((. // []) | map(select(
          (((.ruleId // "") as $r | $rules | index($r)) != null
           and ((.locations[0].physicalLocation.artifactLocation.uri // "")
                | sub("^\\./"; "") | sub("^file://"; "") | ltrimstr($pwd) | . as $u | $paths | index($u)) != null)
          | not)))' "${OUT}/semgrep.sarif" > "${OUT}/semgrep.sarif.tmp" \
        && mv "${OUT}/semgrep.sarif.tmp" "${OUT}/semgrep.sarif"
    fi
  fi
  if [[ $GO -eq 1 ]] && need gosec gosec security; then
    run gosec gosec -quiet -severity medium -exclude-dir=vendor -fmt sarif -out "${OUT}/gosec.sarif" "${GO_PKGS[@]}"
  fi
  if [[ $PY -eq 1 ]] && need bandit bandit security; then
    run bandit bandit -r "${PY_T[@]}" -ll -q -f sarif -o "${OUT}/bandit.sarif" \
      -x "./.venv,./venv,./node_modules,./vendor,./tests,./.quality"
  fi
  if [[ $JS -eq 1 ]] && need biome biome-security security; then
    run biome-security biome lint --no-errors-on-unmatched --only=security \
      --reporter=sarif --reporter-file="${OUT}/biome-security.sarif" "${JS_T[@]}"
  fi
fi

# ---------------------------------------------------------------- dead code
if wants deadcode; then
  if [[ $GO_ALL -eq 1 ]]; then
    if need deadcode deadcode deadcode; then
      run deadcode deadcode -test ./...
      emit_text deadcode deadcode unreachable "${OUT}/deadcode.log"
      rm -f "${OUT}/deadcode.exit"
    fi
    if need staticcheck staticcheck-u1000 deadcode; then
      staticcheck -f sarif -checks U1000 ./... > "${OUT}/staticcheck-u1000.sarif" 2> "${OUT}/staticcheck-u1000.log"
      echo "$?" > "${OUT}/staticcheck-u1000.exit"
    fi
  fi
  if [[ $PY_ALL -eq 1 ]] && need vulture vulture deadcode; then
    run vulture vulture . --min-confidence 80 --exclude ".venv,venv,node_modules,vendor,.quality"
    emit_text vulture deadcode unused "${OUT}/vulture.log"
    rm -f "${OUT}/vulture.exit"
  fi
  if [[ $JS_ALL -eq 1 && -f package.json ]] && need knip knip deadcode; then
    knip --reporter json --no-progress --no-exit-code > "${OUT}/knip.json" 2> "${OUT}/knip.log"
    echo "$?" > "${OUT}/knip.exit"
  fi
fi

# ---------------------------------------------------------------- complexity
if wants complexity; then
  if [[ $GO -eq 1 ]]; then
    mapfile -t p_go < <(list_files go)
    if [[ ${#p_go[@]} -gt 0 ]]; then
      for p_pair in "gocyclo:cyclomatic:${CYCLOMATIC_MAX}" "gocognit:cognitive:${COGNITIVE_MAX}"; do
        IFS=':' read -r p_bin p_kind p_max <<< "$p_pair"
        need "$p_bin" "$p_bin" complexity || continue
        "$p_bin" -over "$p_max" "${p_go[@]}" > "${OUT}/${p_bin}.log" 2>&1
        # "<complexity> <pkg> <func> <file>:<line>:<col>"
        while read -r p_score _ p_func p_pos; do
          [[ "$p_score" =~ ^[0-9]+$ ]] || continue
          emit "$p_bin" complexity "$p_kind" "${p_pos%%:*}" "$(echo "$p_pos" | cut -d: -f2)" \
            "${p_kind} complexity of ${p_func} is ${p_score} (max ${p_max})"
        done < "${OUT}/${p_bin}.log"
      done
    fi
  fi
  if [[ $PY -eq 1 ]]; then
    if need radon radon complexity; then
      radon cc -j -e ".venv/*,venv/*,node_modules/*,vendor/*" "${PY_T[@]}" > "${OUT}/radon.json" 2> "${OUT}/radon.log"
      echo "$?" > "${OUT}/radon.exit"
    fi
    if need complexipy complexipy complexity; then
      run_per_root complexipy complexipy "{ROOT}" --max-complexity-allowed "$COGNITIVE_MAX" --failed --quiet \
        --output-format sarif --output "{SARIF}" \
        --exclude ".venv" --exclude "venv" --exclude "node_modules" --exclude "vendor"
    fi
  fi
  # Oxlint: cyclomatic (`eslint/complexity`) + cognitive (`sonarjs/cognitive-complexity`); Biome keeps format/lint/security.
  if [[ $JS -eq 1 ]] && need oxlint oxlint complexity; then
    oxlint -c .oxlintrc.json -f sarif "${JS_T[@]}" > "${OUT}/oxlint.sarif" 2> "${OUT}/oxlint.log"
    echo "$?" > "${OUT}/oxlint.exit"
  fi
fi

# ---------------------------------------------------------------- duplication
if wants duplication && need jscpd jscpd duplication; then
  run jscpd jscpd . --config .jscpd.json --threshold 100 --reporters json --output "${OUT}/jscpd" --silent
fi

# ---------------------------------------------------------------- tests
run_tests() {
  local p_name="$1" p_cmd="$2"
  if bash -c "$p_cmd" > "${OUT}/${p_name}.log" 2>&1; then
    return 0
  fi
  emit "$p_name" tests "tests-failed" "" 0 "\`${p_cmd}\` failed: $(tail -n 15 "${OUT}/${p_name}.log" | tr '\n' ' ' | cut -c1-1500)"
}

test_cmd() {
  local p_stack="$1" p_default="$2"
  local p_cmd
  p_cmd="$(baseline "test_commands.${p_stack}" "")"
  [[ -n "$p_cmd" ]] && { echo "$p_cmd"; return; }
  echo "$p_default"
}

if wants tests; then
  if [[ $GO_ALL -eq 1 && -f go.mod ]]; then
    run_tests tests-go "$(test_cmd go 'go test ./...')"
  fi
  if [[ $PY_ALL -eq 1 ]] && [[ -n "$(list_all_files py | grep -E '(^|/)(test_[^/]*|[^/]*_test)\.py$' | head -1)" ]]; then
    p_default="pytest -q"
    [[ -f uv.lock || -f pyproject.toml ]] && p_default="uv run pytest -q"
    run_tests tests-python "$(test_cmd python "$p_default")"
  fi
  if [[ $JS_ALL -eq 1 && -f package.json ]] && jq -e '.scripts.test' package.json >/dev/null 2>&1; then
    p_pm="npm"
    [[ -f pnpm-lock.yaml ]] && p_pm="pnpm"
    [[ -f yarn.lock ]] && p_pm="yarn"
    [[ -f bun.lockb || -f bun.lock ]] && p_pm="bun"
    run_tests tests-js "$(test_cmd js "${p_pm} test")"
  fi
fi

# ---------------------------------------------------------------- report
p_scope="$(printf '%s\n' "${SCOPE[@]+"${SCOPE[@]}"}" | jq -R . | jq -cs 'map(select(length > 0))')"
"$(dirname "${BASH_SOURCE[0]}")/aggregate.sh" \
  --stages "$(join_by ',' "${STAGES[@]}")" \
  --scope "$p_scope" \
  --cyclomatic-max "$CYCLOMATIC_MAX" \
  --cognitive-max "$COGNITIVE_MAX" \
  --duplication-max "$DUPLICATION_MAX"
